import{_ as t,o as r,c as n,ag as e}from"./chunks/framework.D5hoimZQ.js";const h=JSON.parse('{"title":"🔬 科学日报 | 2026年8月6日 · 深度扩展","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/science-daily/2026-08-06.md","filePath":"science-log/src/science-daily/2026-08-06.md"}'),s={name:"science-log/src/science-daily/2026-08-06.md"};function a(i,o,g,c,p,d){return r(),n("div",null,[...o[0]||(o[0]=[e('<h1 id="🔬-科学日报-2026年8月6日-·-深度扩展" tabindex="-1">🔬 科学日报 | 2026年8月6日 · 深度扩展 <a class="header-anchor" href="#🔬-科学日报-2026年8月6日-·-深度扩展" aria-label="Permalink to &quot;🔬 科学日报 | 2026年8月6日 · 深度扩展&quot;">​</a></h1><blockquote><p>来源：重建版简讯 <code>reconstructed/2026-08-06.md</code>（🔬 科学前沿 5 篇 / 🤖 AI 前沿 5 篇，共 10 条） 分析日期：2026-08-06 版本：扩展版（10 条深度 + 交叉关联） ⚠️ 本日简讯为<strong>事后重建版</strong>（2026-11-05 按 arXiv/CrossRef 日期回溯生成，非当日发布原文，不代表历史原貌） 核验说明：10 条均于 2026-11-05 联网核验——期刊条目走 CrossRef <code>api.crossref.org/journals|prefixes</code> 按 <code>from-pub-date/until-pub-date</code> 检索并以 EuropePMC <code>resultType=core</code> 取摘要、作者；预印本走 <code>export.arxiv.org/api/query?id_list=...</code> 取 summary 与作者。下列作者、数字、期刊均来自 API 返回值；API 未给出者不补充、不推测。</p></blockquote><hr><h2 id="🔬-一、科学前沿" tabindex="-1">🔬 一、科学前沿 <a class="header-anchor" href="#🔬-一、科学前沿" aria-label="Permalink to &quot;🔬 一、科学前沿&quot;">​</a></h2><h3 id="_1-ai-业务化台风预报-粗网格打赢区域模式" tabindex="-1">1. AI 业务化台风预报：粗网格打赢区域模式 <a class="header-anchor" href="#_1-ai-业务化台风预报-粗网格打赢区域模式" aria-label="Permalink to &quot;1. AI 业务化台风预报：粗网格打赢区域模式&quot;">​</a></h3><p><strong>原文</strong>：Google DeepMind 的 F. Alet、T. R. Andersson、I. Price、S. Markou 等提出 WeatherNext Cyclones（WN-C）：一个业务化的 AI 集合预报模型，用全球分析场加历史热带气旋数据库训练，直接生成 15 天、最多 1,000 成员的全球天气与气旋情景集合。在 2023–2025 年的气旋样本上，其路径、强度与风圈半径预报相对主流业务模式平均取得 1 天以上的预报时效优势——相当于过去十年业务模式发展的总进步量。更反直觉的是它用的输入比区域模式粗几个数量级，说明高分辨率并非强度预报的必要前提，粗分辨率大气场里本就存在比此前认为更多的强度信号；把 WN-C 并入加权平均共识集合能显著提升技巧。</p><p><strong>深度扩展</strong>：</p><p>先说清楚「1 天时效优势」意味着什么。业务上这句等价于：同一场台风，WN-C 在第 4 天给出的强度预报，与现有主流模式第 3 天的水平相当——而强度预报的十年进步量本就以「每年几小时的时效」计，所以这里是压缩式的前进。</p><p>方法上值得注意三点。第一，<strong>训练数据是双源的</strong>：全球分析场（再分析/业务分析，时空连续但分辨率粗）与历史热带气旋数据库（稀疏但含气旋中心、强度、风圈半径这类人工定位的结构化观测）。后者是把「气旋专属信息」注入通用天气模型的接口，缺了它模型不会知道「强度」这个特定标量该怎么定义。第二，<strong>预测对象是全集成的概率分布</strong>：15 天、成员数最大 1,000。成员数是概率预报的硬通货——50 成员集合对 1% 尾部事件的样本只有半个，1,000 成员才有 10 个样本，这直接决定「百年一遇」这类量能不能报。第三，<strong>评估窗口是 2023–2025 的实测气旋</strong>，覆盖了近年来几个快速增强个例，这类个例历来是强度预报的主要失败模式。</p><p>最值得记住的结论是那句「高分辨率不是必要条件」。区域模式追求公里级网格，是为了显式解析眼墙、对流塔；但如果强度的主导信号在大尺度环境（海温、垂直风切变、上层流出、干空气入侵），那么把这些场喂好、把集合采样做够，粗网格也能拿到同样的信息。这并不否定高分辨率的价值，而是指出：此前把「分辨率不足」当成强度预报瓶颈的诊断，可能把因果归错了位置。</p><p><strong>跨主题关联</strong>：与 <code>topics/earth-science/index.md</code> 里已有的数值预报/再分析线索直接相接；对 <code>topics/wind-energy/index.md</code> 更实际——台风路径与风圈半径的 1 天提前量，直接改变海上风电的预警停机、切出策略与载荷评估窗口。</p><hr><h3 id="_2-悬浮磁体磁强计-32-ft-√hz-室温台面" tabindex="-1">2. 悬浮磁体磁强计：32 fT/√Hz，室温台面 <a class="header-anchor" href="#_2-悬浮磁体磁强计-32-ft-√hz-室温台面" aria-label="Permalink to &quot;2. 悬浮磁体磁强计：32 fT/√Hz，室温台面&quot;">​</a></h3><p><strong>原文</strong>：W. Ji、C. Xu、G. Qu、D. Budker 演示了一个抗磁稳定 + 磁悬浮的磁体磁强计：用光学方法读出悬浮磁体的运动。实测灵敏度达 32 fT/√Hz，与超导量子干涉器件（SQUID）和原子磁强计同一量级，却不需要低温，且能在地磁场环境下工作。</p><p><strong>深度扩展</strong>：</p><p>磁测量的灵敏度阶梯长期由两个技术族瓜分：SQUID（几 fT/√Hz，必须液氦/液氮）与原子磁强计（光泵/自旋交换无弛豫，无屏蔽下约 10 fT/√Hz 量级）。这篇的路线是第三条：<strong>把一块小磁体用抗磁稳定 + 磁悬浮悬在空中，用光测它的位移</strong>。</p><p>为什么「悬浮」等于「灵敏」？任何力学传感器都被两条链锁住：机械自由度必须与环境的噪声通道（夹具的振动、热传导、材料内耗）解耦，而夹持必然引入损耗（低 Q）与热接触。悬浮把这两条同时切断——没有接触就没有声子泄漏，Q 可以做得很高，于是对力的响应（位移/力）变大，同样位移噪声下可测的力更小；再借磁矩把「力」换算成「场」，就得到磁强计。代价是必须解决<strong>稳定性</strong>：恩肖定理（Earnshaw）禁止静态场中纯磁悬浮稳定，所以需要抗磁体（或旋转、或主动反馈）提供恢复力。作者用的是抗磁稳定方案，这解释了为什么它能在室温、地磁场下长期悬停而不失稳。</p><p>数字要辩证地看：32 fT/√Hz 是<strong>灵敏度</strong>（单位带宽噪声底），不等于<strong>分辨率</strong>（能分辨多小的场变化），也不等于<strong>准确度</strong>。但它已经落在脑磁（MEG，皮层场 10²–10³ fT）与心脏磁场（10⁴ fT 量级）的可用区间内，而这两件事此前几乎只能在磁屏蔽室内用 SQUID 做。室温、可贴近头皮、无需液氦，这三点合起来是「可穿戴 MEG」的门票——同日 Nature 的新闻版把它直接解读为「可能探测极微弱脑活动」，判断是准确的。</p><p><strong>跨主题关联</strong>：<code>topics/physics/index.md</code> 的精密测量与噪声谱学线索；<code>topics/quantum-physics/index.md</code> 里超导器件与自旋体系的灵敏度比较基准；对 <code>topics/neuroscience/index.md</code> 是工具级影响——MEG 若摆脱屏蔽室与液氦，脑节律研究的样本量与范式都会变。</p><hr><h3 id="_3-用基因组语言模型「生成」活噬菌体" tabindex="-1">3. 用基因组语言模型「生成」活噬菌体 <a class="header-anchor" href="#_3-用基因组语言模型「生成」活噬菌体" aria-label="Permalink to &quot;3. 用基因组语言模型「生成」活噬菌体&quot;">​</a></h3><p><strong>原文</strong>：S. H. King、C. L. Driscoll、D. B. Li、D. Guo、M. E. Wilkinson、B. L. Hie 等报告了首次用基因组语言模型生成完整噬菌体基因组：以噬菌体 ΦX174 为设计模板，生成具备目标宿主嗜性的基因组。实验测试得到 16 株可存活、适应度谱各异的噬菌体；冷冻电镜证实其中一株使用的是演化上相距甚远的 DNA 包装蛋白来组装衣壳。由生成噬菌体组成的鸡尾酒能迅速压制对 ΦX174 已产生抗性的大肠杆菌。</p><p><strong>深度扩展</strong>：</p><p>这项工作的分量在「尺度」二字。此前生成式蛋白设计已经能从零做出新的折叠、新的结合界面，甚至整条人工设计的多亚基组装体；但从<strong>单个蛋白</strong>跨到<strong>整个基因组</strong>，中间隔着一整类约束：基因要首尾相接、密码子使用要与宿主 tRNA 池匹配、mRNA 二级结构不能把核糖体结合位点埋掉、重叠基因（ΦX174 是这方面的经典标本，5,386 nt 的环状单链 DNA 里基因 E 完全嵌在基因 D 内）意味着任何一个碱基改动同时属于两个阅读框。</p><p>所以出题方式不是「造一个新蛋白」，而是「在 ΦX174 的模板上做<strong>可行域内的采样</strong>」：保留整体架构与必需元件，让模型在满足全部耦合约束的前提下重写序列，并把「宿主嗜性」作为可控条件。16 株可存活、且适应度谱各异，说明模型不是在复刻野生型——如果只是记忆，产物会挤在适应度的高点上，不会散开。最硬的一条证据是冷冻电镜那株：它用的是<strong>演化上相距很远的 DNA 包装蛋白</strong>来装衣壳，即模型把一套「非本家族」的解决方案拼进了可运行的基因组，这在纯序列相似性驱动的设计里几乎不会出现，只有模型学到了「功能等价」而非「序列相似」才解释得通。</p><p>应用面直接指向噬菌体疗法：细菌对噬菌体产生抗性是疗法的主要失效模式，而「生成 + 鸡尾酒」把对策从「去自然界筛新噬菌体」变成「按需合成一批表面/受体结合特性各异的噬菌体」。边界同样清楚：实验在实验室条件、以大肠杆菌与 ΦX174 为体系；体内药代、免疫清除、以及大规模生产的合规路径都不在这篇的射程内。</p><p><strong>跨主题关联</strong>：<code>topics/biomedicine/index.md</code> 的抗生素替代/噬菌体疗法线索；方法学上与 <code>topics/ai-system-architecture/index.md</code> 的「在硬约束下做生成式采样」同构——约束不是过滤器，而是搜索空间的定义。</p><hr><h3 id="_4-θ-扫掠是一种「注意力」" tabindex="-1">4. θ 扫掠是一种「注意力」 <a class="header-anchor" href="#_4-θ-扫掠是一种「注意力」" aria-label="Permalink to &quot;4. θ 扫掠是一种「注意力」&quot;">​</a></h3><p><strong>原文</strong>：A. Z. Vollan、M. F. Schellenberger、R. J. Gardner、M.-B. Moser、E. I. Moser 用自由活动大鼠的大规模 Neuropixels 记录证明：扫掠与方向信号都能快速动态调制——追逐时跟踪移动目标、静止时先于定向反应出现、倒退行走时方向反转，且无需事先学会目标位置；REM 睡眠中出现类似调制。结论是扫掠构成一种类注意机制，用于选择性采样「以世界为参照」的认知地图。</p><p><strong>深度扩展</strong>：</p><p>先把现象讲清楚。大鼠海马 theta 节律（约 6–10 Hz）下，位置细胞与网格细胞的放电时刻在 theta 周期内随位置系统性地提前——这就是「扫掠」：一群细胞的感受野不是被同时读出，而是在一个 theta 周期内被<strong>按空间顺序快速扫过</strong>，等于用时间复用了一维读出通道。Moser 实验室此前的工作进一步发现扫掠是<strong>左右交替</strong>的：相邻 theta 周期分别扫向身体左侧与右侧空间，由副下托（parasubiculum）的方向信号协调。交替的意义是「在探索时保证均匀覆盖」——不偏向任何一侧。</p><p>这篇的新结果是：均匀覆盖不是硬接线，而是<strong>可调参数</strong>。三条行为证据各有分量。追逐移动目标时，扫掠偏向目标方向——采样被需求拉动；静止不动时，扫掠<strong>先于</strong>定向反应出现——顺序说明它是「准备去看」而不是「看完了的副产品」；倒退行走时扫掠方向反转——排除了「扫掠方向 = 头部朝向」这种简单解释，因为倒退时头部朝向与运动方向相反，而扫掠跟的是运动/注意的方向。最关键的对照是「无需事先学会目标位置」：这排除了「学习改变了地图」的解释，把效应锁在<strong>在线调制</strong>上。REM 睡眠中同类调制出现，进一步说明这套机制不需要感觉输入驱动。</p><p>用一句话概括：扫掠不是地图的读时钟，而是<strong>可编程的采样器</strong>——它在「以世界为参照（allocentric）」的坐标系里做选择性读取，功能上等价于注意力在感觉皮层做的事，只是作用对象是内部地图而非外部刺激。</p><p><strong>跨主题关联</strong>：<code>topics/neuroscience/index.md</code> 的海马—内嗅系统与 theta 节律线索；与 <code>topics/ai-brain/index.md</code> 的核心判断同构——「读取策略」本身就是一种知识，检索器如何扫过记忆决定了系统能想到什么。</p><hr><h3 id="_5-ai-设计的-protac-清除-clip1–ltk-融合蛋白" tabindex="-1">5. AI 设计的 PROTAC 清除 CLIP1–LTK 融合蛋白 <a class="header-anchor" href="#_5-ai-设计的-protac-清除-clip1–ltk-融合蛋白" aria-label="Permalink to &quot;5. AI 设计的 PROTAC 清除 CLIP1–LTK 融合蛋白&quot;">​</a></h3><p><strong>原文</strong>：CLIP1–LTK 融合的致癌性不只来自 LTK 激酶活性，还依赖 CLIP1 介导的多聚化这一非催化功能；现有 ALK 抑制剂只压激酶，脚手架功能原封不动，耐药随之而来。S. Chen、H. Duan、S. Zhong、J. Ge、P. Pan 等把三元复合物预测的深度学习模型与基于结构的分子优化结合，设计出首个体内可用的 CLIP1–LTK 降解剂 DCL05：口服可吸收，降解效力达 DC50 = 40 pM，并在体外与体内广谱优于现有激酶抑制剂（含多种 LTK 耐药相关突变）。</p><p><strong>深度扩展</strong>：</p><p>CLIP1–LTK 是 2021 年前后在部分非小细胞肺癌中被鉴定出的融合驱动基因：CLIP1 提供卷曲螺旋结构域，使融合蛋白<strong>自发多聚化</strong>，从而在不依赖配体的前提下让 LTK 激酶域反式互激。这带来一个药理学上的两难：ALK 抑制剂能压住激酶活性，但多聚化的脚手架仍在，信号可以通过二聚体界面的旁路与激酶域突变重新起来——这正是临床上「先响应、后耐药」的典型剧本。</p><p>PROTAC（蛋白水解靶向嵌合体）的正确之处在于它改的是<strong>蛋白的量</strong>而不是活性：一端结合靶蛋白、一端招募 E3 连接酶，形成三元复合物后给靶蛋白挂上泛素链，由蛋白酶体销毁。它的两个固有难点也在这里：其一，三元复合物的几何难以先验预测（不是「A 结合 B」那么简单，而是「A–ligand–B」的空间排布要能让泛素化发生在正确的赖氨酸上）；其二，PROTAC 分子量大、极性高，口服吸收差。</p><p>DCL05 的设计流程正对着这两点：先用<strong>深度学习模型预测三元复合物</strong>，在结构层面筛选能形成有效几何的连接子构型，再以基于结构的方法做分子优化（补上成药性、口服暴露）。结果给出两个硬数字——<strong>DC50 = 40 pM</strong>（皮摩尔级降解半数浓度，等于「极低浓度就能把靶蛋白清掉」）与体内口服有效；并且在广谱 LTK 耐药突变上优于激酶抑制剂，这一点是机制层面的必然推论：激酶抑制剂要跟突变后的 ATP 口袋较劲，而降解剂只要结合位点还在（或即使活性下降，只要三元复合物能形成），蛋白酶体并不在乎激酶域是否突变。</p><p>边界：这是单一融合驱动模型的临床前工作，人体剂量、长期泛素—蛋白酶体负荷、以及正常组织里 LTK 表达带来的靶向/脱靶毒性，都还没进入这篇的证据范围。</p><p><strong>跨主题关联</strong>：<code>topics/biomedicine/index.md</code> 的靶向降解与耐药演化线索；「降解 &gt; 抑制」这一转向，与 <code>topics/ai-system-architecture/index.md</code> 的「删除通路比压制输出更彻底」是同一逻辑的两个实例。</p><hr><h2 id="🤖-二、ai-前沿" tabindex="-1">🤖 二、AI 前沿 <a class="header-anchor" href="#🤖-二、ai-前沿" aria-label="Permalink to &quot;🤖 二、AI 前沿&quot;">​</a></h2><h3 id="_6-从黑盒里「撬出」glu-前馈块" tabindex="-1">6. 从黑盒里「撬出」GLU 前馈块 <a class="header-anchor" href="#_6-从黑盒里「撬出」glu-前馈块" aria-label="Permalink to &quot;6. 从黑盒里「撬出」GLU 前馈块&quot;">​</a></h3><p><strong>原文</strong>：Chunhui Shi、Xinwen Fu 给出一个构造性的多阶段前向查询恢复原语：用有限差分曲率给出门控方向候选，再用 x 与 −x 的成对观测分离门控幅度、朝向与值支耦合。在高精度目标上，六个 Qwen 层、一个 8,192 单元的 Llama 子问题与一个全维 Gemma 块都达到中位验证误差低于 1%；四种有限精度配置仍保持中位误差 5% 以内，但没有一种能复现每一个存储权重。作者明确划界：这是隔离块实验，尚非端到端模型 API 攻击。</p><p><strong>深度扩展</strong>：</p><p>权重提取的攻击模型很朴素：只给前向接口（黑盒），能否把参数反解出来？这类工作有现实意义——模型权重是核心资产，若 API 级前向查询就能抽走，商业与安全边界都会变。此前已有的成果分两类：ReLU 网络（分段线性，靠断点定位逐神经元解出）、逐元素激活网络（GELU/SiLU，靠二阶信息），以及 Transformer 的末层投影（单层线性，最易解）。GLU 前馈块被剩下来是有结构性原因的：它有<strong>两条支路</strong>，一条过激活函数（门），另一条不过（值），两者逐元素相乘。乘法把「门」与「值」的信息搅在一起，任何只看输出的线性探测都拿不到可分的信号。</p><p>作者的破法分三步。第一步，<strong>有限差分曲率</strong>：对局部输入做二阶差分，曲率的各向异性里含有门控方向的信息，于是先得到一批「方向候选」。第二步，<strong>反对偶成对观测</strong>：同时查询 x 与 −x，两条输出的差异把门控的幅度与朝向从耦合项里剥出来——这一步是整篇的关键技巧，因为乘性耦合在 x ↔ −x 变换下会显出不同的符号结构。第三步，多阶段迭代，逐步把值支的线性映射解出。评估覆盖了三个真实模型族（Qwen 的六个层、Llama 一个 8,192 单元的子问题、一个全维 Gemma 块），高精度目标下中位验证误差都 <strong>低于 1%</strong>。</p><p>但作者的自我限制写得很诚实，也是这篇最该被记住的部分：<strong>没有一种配置能复现每一个存储权重</strong>，且这是「孤立块」实验——真实攻击要从最终 logits 反推中间层的块响应，而那一步未解。换句话说，它证明的是「GLU 块在信息上不是不可提取的」，而不是「你现在就能偷走一个 API 后面的模型」。</p><p><strong>跨主题关联</strong>：<code>topics/cybersecurity/index.md</code> 的模型资产/侧信道攻击线索；与 <code>topics/ai-system-architecture/index.md</code> 的「能力可被外部读出」问题直接相关——权重可提取性是一种不依赖内部访问的泄漏面。</p><hr><h3 id="_7-最优-agnostic-pac-学习-样本复杂度在常数因子内闭合" tabindex="-1">7. 最优 agnostic PAC 学习：样本复杂度在常数因子内闭合 <a class="header-anchor" href="#_7-最优-agnostic-pac-学习-样本复杂度在常数因子内闭合" aria-label="Permalink to &quot;7. 最优 agnostic PAC 学习：样本复杂度在常数因子内闭合&quot;">​</a></h3><p><strong>原文</strong>：Markus Engelund Mathiasen、Jian Qian、Nikita Zhivotovskiy 构造出一个学习器，从 n 个 i.i.d. 样本出发，对任意 0 &lt; δ ≤ 1/2，以至少 1−δ 的概率满足 L(ĥ) ≤ L* + 7×10⁸·(√(L*(d+log(1/δ))/n) + (d+log(1/δ))/n)。这条界在每一个固定 L* 处都匹配 Devroye、Györfi、Lugosi（1996）给出的下界，因此把 agnostic PAC 学习的样本复杂度在通用常数因子内彻底定死。</p><p><strong>深度扩展</strong>：</p><p>先解释这个问题的形状。在可实现（realizable）情形，若存在零风险的假设，学习所需样本量是 Θ((d + log(1/δ))/ε)：VC 维 d 决定「假设类有多复杂」，1/ε 决定「要多准」。而在 agnostic 情形（数据可能根本不由 H 中任何假设生成、最小风险 L* &gt; 0），最优界长期是开放问题的一个精细角落：已知的界分成两种 regime，一种在 L* 很小时退化成 √(L*·d/n) 型（因为坏假设的超额风险天然被 L* 压住），另一种是常规的 √(d/n) 型。真正的问题是：<em><em>是否存在一个算法同时在所有 L</em> 处达到最优？</em>*</p><p>这篇的回答是肯定的，且给出了显式的界：超额风险 ≈ √(L*(d+log(1/δ))/n) + (d+log(1/δ))/n。第一项是「相对误差」型——L* 越小，允许的超额风险越小，这是 agnostic 问题的本质结构（局部化的 Bernstein 型行为）；第二项是不可避免的「维数税」，因为即使 L* = 0 也要付出 d/n 量级的代价。两项相加，每个固定 L* 处都与 1996 年的下界匹配，于是样本复杂度被定在常数因子内——这在统计学习理论里是「问题关闭」量级的结论。</p><p>必须说清这个常数：7×10⁸。这显然没有任何实用价值，算法本身很可能涉及精细的、依赖未知参数的多阶段结构（例如先在多个候选 regime 间做模型选择，再用局部化的经验风险最小化）。理论结果的意义不在工程，而在于<strong>确认了最优速率的形状</strong>：它告诉我们此前那些只覆盖部分 regime 的算法不是「还不够聪明」，而是「差在同一处」，且这一处是可以被跨过的。它也解释了为什么经验上小 L* 任务的泛化曲线会偏离 √(1/n) 的直觉——相对误差项让曲线更陡。</p><p><strong>跨主题关联</strong>：<code>topics/intelligence-self-learning/index.md</code> 的泛化/样本效率线索；<code>topics/ai-system-architecture/index.md</code> 里「模型选择与局部化估计」的工程对应物——分 regime 处理不是工程凑合，而是最优解的必需结构。</p><hr><h3 id="_8-stepjack-把恶意目标拆成无害小步" tabindex="-1">8. StepJack：把恶意目标拆成无害小步 <a class="header-anchor" href="#_8-stepjack-把恶意目标拆成无害小步" aria-label="Permalink to &quot;8. StepJack：把恶意目标拆成无害小步&quot;">​</a></h3><p><strong>原文</strong>：Zhuoxin Zhan、Akbar Rafiey、Avery Ma、Leila Pishdad、Layla El Asri 提出多步间接提示注入这一新攻击类：把对抗目标分解成多个看起来无害的子步骤，散布在智能体导航路径上的一条页面链中；并给出自动分解流水线，约束是「子步骤合起来必须达成原目标」，同时优化每个子步骤的无害程度。据此构建基准 StepJack（480 个测试例），评测六个前沿 CUA：在固定分解深度下，多步攻击使六个中的三个成功率上升，最高 +31.2 个百分点（GPT-5.4-mini 从单步 41.7% 升到三步 72.9%）；能可靠沿参考链执行的五个智能体平均从 31.3% 升至 36.9%。</p><p><strong>深度扩展</strong>：</p><p>间接提示注入的经典形态是「网页里写一句恶意指令，智能体照做」。防御侧的对策也随之定型：训练/过滤模型对「单条可疑指令」的敏感度。StepJack 的攻击逻辑是把这条对策的前提拆掉——如果恶意目标不是一个句子，而是一条<strong>链条</strong>，每一个环节单独看都是正常操作（打开这个页面、复制这个字段、粘贴到那里、点提交），那么「指令级」的检测器就无处着力。</p><p>技术核心是那个自动分解流水线，它要同时满足两个互相拉扯的约束：<strong>功能性</strong>（所有子步骤串起来必须真的完成原目标，而不是各做各的）与<strong>无害性</strong>（每个子步骤在孤立语境下都要显得清白）。这不是简单的文本切分，而是一个带目标的搜索：把一个终态目标反解成一串中间状态，再为每个状态迁移找一句「合理的工作性语言」。这也是为什么基准叫 StepJack（jack = 千斤顶，逐步顶起）。</p><p>数据的读法要小心：在六个前沿 CUA 上，多步攻击只让<strong>三个</strong>的成功率上升，最高 +31.2 点；按能在参考链上稳定跟读的五个智能体平均，只从 31.3% 升到 36.9%（+5.6 点）。平均增益不大，说明「多步」本身不是万灵药——链条越长，智能体越容易在某一步走偏或放弃，攻击的<strong>执行成本</strong>也随之上来。真正的信号是方差：某些模型对链条极其脆弱（GPT-5.4-mini 41.7%→72.9%），说明脆弱性不是均匀分布的，而是与「长程指令跟随能力」强相关——越擅长跟长链条任务的模型，越容易被长链条攻击。</p><p><strong>跨主题关联</strong>：<code>topics/cybersecurity/index.md</code> 的提示注入/智能体安全线索；与 <code>topics/ai-system-architecture/index.md</code> 的「威胁模型必须按轨迹而非按单步定义」同构——安全边界应建在会话/轨迹层，而非内容层。</p><hr><h3 id="_9-av-aivat-证据够了就停-评测省-74-倍" tabindex="-1">9. AV-AIVAT：证据够了就停，评测省 74 倍 <a class="header-anchor" href="#_9-av-aivat-证据够了就停-评测省-74-倍" aria-label="Permalink to &quot;9. AV-AIVAT：证据够了就停，评测省 74 倍&quot;">​</a></h3><p><strong>原文</strong>：Boning Li、Yu Chen、Longbo Huang 把三步合成一体：AIVAT 用条件均值为零的修正降低不完全信息博弈的方差（15 组 LLM 智能体配置、71,439 手一对一无限注德州扑克，中位方差降 54 倍），但它不告诉你何时停；再与持续监控的置信序列（CS）结合成 anytime-valid 版本，且在线价值模型只用过去的牌局学习，避免任何一局给自己的修正「打分」。在 95% 名义水平、±1 大盲的目标精度下，未修正的原始结果需要中位 74 倍的手数才能停；精确的有限样本认证改用经验 Bernstein CS，需对修正后收益的界有独立依据，作者对 Leduc 扑克给出结构性证明，并刻画了由下注上限与该界共同决定的宽度地板。</p><p><strong>深度扩展</strong>：</p><p>先把统计结构讲清楚，因为这是全篇的骨头。评测两个智能体强弱 = 估计两个分布的均值之差，而扑克的噪声极大（运气）：单局结果的方差远大于真实技巧差，所以固定预算评测要么烧钱，要么给出无结论。<strong>AIVAT</strong> 的贡献是降方差：它用一手牌的全部可观测信息（对手底牌、公共牌、下注历史）计算一个条件期望为零的修正项，把「运气」这一部分从结果里解析地减掉。条件是价值模型必须只看<strong>过去</strong>的牌局——否则修正项会用到这局自己的结果，等于作弊，估计会有偏。</p><p><strong>顺序检验</strong>的地位在这里才显出必要性。如果样本量事先固定，普通置信区间就够了；但「边打边看、显著就停」会让名义 95% 的实际覆盖率崩掉（可选停止问题：你在噪声高的时刻更容易撞到显著）。置信序列（CS）解决这个：它对<strong>所有</strong> t 同时成立，因此任意停止时刻的结论仍然有效。于是「省 74 倍」这个数字不是靠放松标准得来的，而是「不再为已定的结论继续付费」的纯收益。</p><p>作者还做了一个诚实的分层：<strong>渐近 CS（AsympCS）用于筛选，精确的有限样本认证用经验 Bernstein CS（EB-CS）</strong>，后者要求对修正后收益有独立可证的界——他们对 Leduc 扑克给出了结构性证明，并刻画出「宽度地板」：CS 的下注上限与这个界共同决定了即使方差降到零，停止也不会无限快。这解释了为什么 HUNL 上的 EB-CS 只有中位 1.37 倍的停止时间比（相对保守），而 AsympCS 能拿到 74 倍——<strong>渐近效率与有限样本保证之间的可量化差距</strong>，被清楚地摆在了台面上。</p><p>工程含义直接：模型/智能体 A-B 测试、排行榜、红队对比，都可以从「跑满 N 局」改成「证据够了就停 + 附带可复核的停止时刻证书」，第三方能在同一停止点重新验算结论。</p><p><strong>跨主题关联</strong>：<code>topics/intelligence-self-learning/index.md</code> 的评测方法论线索；<code>topics/investment-methods/index.md</code> 里的统计显著性/序贯检验同族问题——A/B 与策略回测的「偷看即失效」是同一个定理。</p><hr><h3 id="_10-生产环境-352-万次改动-ai-写的-c-有自己的质量剖面" tabindex="-1">10. 生产环境 352 万次改动：AI 写的 C++ 有自己的质量剖面 <a class="header-anchor" href="#_10-生产环境-352-万次改动-ai-写的-c-有自己的质量剖面" aria-label="Permalink to &quot;10. 生产环境 352 万次改动：AI 写的 C++ 有自己的质量剖面&quot;">​</a></h3><p><strong>原文</strong>：Michael Tran、Fred Lewis、Kun Yang、Saksham Thakur、Aditya Kini 等在一家支撑数十亿用户的大型企业内部做了大规模实证：2025 年 4 月至 2026 年 4 月，追踪棕色地带代码库中 352 万次代码改动，逐行对比 AI 生成与人类编写的 C++。结果是 AI 代码有清晰可辨的质量剖面——更高的接口与耦合负担、拷贝与分配开销，以及偏好显式循环而非优化过的标准库 API；这些差异转化为真实下游成本：评审负担上升，计算资源消耗增加 5–8%。但作者也给出可操作的解：向模型提供分类学指导的定向反馈，可使目标静态分析告警减少 11.1%，并改善计算效率。</p><p><strong>深度扩展</strong>：</p><p>这类研究最难的不是统计，而是<strong>可观测性</strong>：在真实企业里，「这段代码是 AI 写的」与「它上线后表现如何」通常分属两个系统，无法逐行对齐。作者所在的机构恰好具备两件事——每一行上线代码都有归属与遥测，以及一个足够大的棕色地带（brownfield）C++ 代码库。于是有了这个样本：<strong>352 万次改动、12 个月</strong>，在同一代码库内做 AI 与人类的对照（天然控制了项目、语言、评审流程）。</p><p>三条质量剖面值得逐条读。<strong>接口与耦合负担</strong>：AI 倾向于新增接口/依赖而不是复用既有的，短期看是「加了个函数就完成任务」，长期看是把耦合度往上推——这正是维护成本的主要来源。<strong>拷贝与分配开销</strong>：C++ 里最贵的是隐式拷贝与非必要堆分配，AI 常写出按值传递大对象、在热路径里构造临时容器的代码。<strong>偏好显式循环而非优化过的标准库算法</strong>：手写 <code>for</code> 循环在语义上更「直白」，但放弃了 <code>std::sort</code>/<code>std::transform</code> 等实现里的向量化与分支预测优化。这三条合起来正好解释那个硬数字：<strong>计算资源消耗增加 5–8%</strong>——在一个支撑数十亿用户的系统里，5% 的算力是巨额账单。</p><p>最有价值的部分是后半段：给模型<strong>分类学指导的定向反馈</strong>（即把「接口膨胀、隐式拷贝、放弃标准算法」这类缺陷整理成明确的分类与判据，在生成/评审时回灌），目标静态分析告警减少 <strong>11.1%</strong>，计算效率改善。这说明 AI 代码的质量剖面不是模型的固有属性，而是<strong>提示与评审信号的函数</strong>——你不告诉它 C++ 的隐性成本在哪，它就按「能跑」的最省力路径写。</p><p><strong>跨主题关联</strong>：<code>topics/vibe-coding/index.md</code> 的 AI 编程实践线索（尤其「生成速度 vs 长期可维护性」的张力）；<code>topics/quality-products/index.md</code> 里「缺陷分类学驱动改进」的同构方法——先建分类，再定点回灌。</p><hr><h2 id="🧠-机制层" tabindex="-1">🧠 机制层 <a class="header-anchor" href="#🧠-机制层" aria-label="Permalink to &quot;🧠 机制层&quot;">​</a></h2><h3 id="机制一-wn-c-为什么能以粗胜细——强度信号在尺度上的分布-集合采样" tabindex="-1">机制一：WN-C 为什么能以粗胜细——强度信号在尺度上的分布 + 集合采样 <a class="header-anchor" href="#机制一-wn-c-为什么能以粗胜细——强度信号在尺度上的分布-集合采样" aria-label="Permalink to &quot;机制一：WN-C 为什么能以粗胜细——强度信号在尺度上的分布 + 集合采样&quot;">​</a></h3><p>热带气旋强度预报的困难可以拆成两个独立问题：<strong>(a) 强度信号的物理来源在哪个尺度上？(b) 把不确定性表达成什么对象？</strong> WN-C 的成绩说明两个问题的答案都跟此前的直觉不同。</p><p><strong>第一段：强度不是眼墙尺度的属性。</strong> 区域模式追公里级网格，逻辑是「必须解析眼墙与对流塔，才能算对强度」。但强度的<strong>约束</strong>主要来自环境：海表温度决定最大可能强度（潜在强度上限），垂直风切变决定暖心能否建立，中层干空气入侵决定对流能否持续，上层流出通道决定质量与角动量能否排出，海洋热含量与冷尾流决定自我削弱的速度。这些量的水平尺度是几百到几千公里，垂直结构在再分析资料里已被同化得很好。也就是说，决定强度的信息<strong>在粗网格上就是完备的</strong>——被粗网格丢掉的只是「眼墙怎么转」这类细节，而细节对 24–72 小时后的强度值影响有限。这是「粗输入不劣」的第一层解释，也是论文所谓「粗大气数据里的强度信号比此前认为的更多」的具体含义。</p><p><strong>第二段：端到端学习把「参数化」换成了「拟合」。</strong> 传统模式里，对流、云微物理、边界层通量都是<strong>参数化</strong>：用一套人工方案把次网格过程映射到大尺度场，误差的主要来源恰恰是这些方案在极端条件下的外推。数据驱动的模型不再写参数化，而是从大量历史分析场/再分析中直接学习「大尺度场 → 未来状态」的映射，等价于把参数化替换成在高维空间里拟合出的经验算子。它在训练分布内自然继承了数值模式已有的物理约束（因为训练标签就来自这些系统），但在<strong>映射本身</strong>上更灵活——这是「以粗胜细」的第二层解释。</p><p><strong>第三段：1,000 成员让「尾部」变成可估计量。</strong> 概率预报的精度不只取决于单个成员的质量，更取决于<strong>集合规模</strong>。若一个事件（如快速增强到超强台风）的概率是 1%，50 成员集合平均只有 0.5 个样本，估计出的概率几乎是噪声；1,000 成员有 10 个样本，相对标准差约 30%，才开始可用。所以「成员数 = 1,000」不是炫技，而是「稀有事件预报」这一目标函数的直接要求。同时，AI 模型单次前向的成本远低于数值模式，才让这个规模在经济上可行——<strong>这是计算成本结构改变带来的方法论变化，而不是精度上的小步改进</strong>。</p><p><strong>第四段：共识集合是收益放大器。</strong> 论文指出把 WN-C 加入加权平均共识集合能显著提升技巧。原因是误差结构互补：AI 模型的误差偏向「平滑/回归均值」（欠极值），数值模式的误差偏向「参数化偏差」，两者加权平均能同时压低方差与偏差。这也给出可检验推论：若共识权重按个例自适应（依流型而非固定权重），技巧应进一步提升。</p><h3 id="机制二-悬浮磁强计的噪声链条——从热运动到-32-ft-√hz" tabindex="-1">机制二：悬浮磁强计的噪声链条——从热运动到 32 fT/√Hz <a class="header-anchor" href="#机制二-悬浮磁强计的噪声链条——从热运动到-32-ft-√hz" aria-label="Permalink to &quot;机制二：悬浮磁强计的噪声链条——从热运动到 32 fT/√Hz&quot;">​</a></h3><p>把一个磁体悬在空中测磁场，看起来只是「换个夹持方式」，实际上是<strong>把传感器的噪声预算整体重写</strong>。链条有四环。</p><p><strong>第一环：机械自由度必须高 Q、低损耗。</strong> 任何力学传感器都可写成受迫阻尼振子：位移对外力的响应在共振附近被 Q 放大，而热噪声力谱密度 S_F = 4k_BTb（b 为阻尼系数）与 Q 成反比。夹持最大的问题不是「不牢」，而是<strong>声子泄漏</strong>：夹具把振动能量带走，等效于给振子并联了一个巨大的阻尼通道，Q 掉到几十甚至更低，灵敏度随之崩塌。悬浮切断接触，把这条通道关掉——这是「悬浮 = 灵敏」的第一性原因，与光学腔里追求高精细度是同一件事。</p><p><strong>第二环：稳定性必须由抗磁提供。</strong> 恩肖定理说：静态磁场里不存在稳定的纯磁悬浮平衡（麦克斯韦方程给出的势在自由空间满足拉普拉斯方程，不可能有局域极小）。所以必须引入第二种机制：抗磁体的磁化率 χ &lt; 0，其能量在磁场中与 |B|² 同号，给出<strong>指向弱场方向的恢复力</strong>——这就是抗磁悬浮（热解石墨悬浮在强磁体上方是教科书例子）。作者反过来用：让一个强磁体被抗磁结构稳定地悬住，磁体自身的运动即被测对象。稳定裕度来自抗磁恢复力的刚度与重力的比值，这解释了为什么它能在室温、地磁场下长期悬停而不失稳。</p><p><strong>第三环：位移必须被光读到极限。</strong> 光测（干涉/腔增强）的位移噪声底由散粒噪声与激光频率/强度噪声共同决定。要达 32 fT/√Hz，位移分辨率必须进到 10⁻¹² m 量级甚至更好——这正是悬浮方案的第二个红利：因为振子 Q 高、响应大，同样的位移噪声对应更小的力噪声。</p><p><strong>第四环：力 → 场的换算引入几何因子。</strong> 磁体在梯度场中受力 F = ∇(m·B)，所以测力等价于测<strong>场梯度</strong>；要报「场灵敏度」，必须用已知的磁矩与几何标定梯度到场的关系。这是这类器件最容易被误读的地方：32 fT/√Hz 是<strong>在给定标定下</strong>的等效场噪声，换几何、换磁矩都会变；它不等于「能分辨 32 fT 的绝对场」，更不等于准确度。真正可比的量是噪声底与带宽、以及在地磁场（数十 μT，比信号大 10⁹ 倍量级）背景下对低频漂移的抑制能力——论文强调「在地磁场下工作」，指的正是这一点：不需要屏蔽室。</p><h3 id="机制三-θ-扫掠的电路基础——时间复用读出-交替方向信号-在线增益" tabindex="-1">机制三：θ 扫掠的电路基础——时间复用读出 + 交替方向信号 + 在线增益 <a class="header-anchor" href="#机制三-θ-扫掠的电路基础——时间复用读出-交替方向信号-在线增益" aria-label="Permalink to &quot;机制三：θ 扫掠的电路基础——时间复用读出 + 交替方向信号 + 在线增益&quot;">​</a></h3><p>海马—内嗅系统要在毫秒尺度上表达「我在哪、我要去哪」，而神经元的数量与放电率都是有限资源。扫掠是这套系统的**时间复用（time-division multiplexing）**方案。</p><p><strong>第一段：相位进动就是扫描。</strong> 位置细胞在 theta 周期内的放电相位随动物进入感受野的深度而系统性提前（phase precession）：越靠后的位置，放电越早。把一群位置细胞的相位—位置关系并置，就得到「在一个 theta 周期（约 100–160 ms）内，群体活动沿空间路径<strong>顺序扫过</strong>一次」。于是空间的序列被编码成时间的序列——这正是「扫掠」二字的来源，也是「用一维时间通道读出二维地图」的具体实现。</p><p><strong>第二段：左右交替来自副下托的方向信号。</strong> 单个 theta 周期只能扫一条线；若每个周期都扫同一侧，覆盖会偏。Moser 实验室的既有工作显示：相邻周期分别扫向身体左/右，由副下托（parasubiculum）提供的方向信号翻转相位，使两侧交替读出。这是一个<strong>几何上的对称性破缺</strong>：交替使长时平均覆盖均匀，而不交替则会系统性地偏向一侧。所以「均匀覆盖」是交替的<strong>目的论解释</strong>，而副下托方向信号是它的<strong>实现机制</strong>。</p><p><strong>第三段：调制发生在增益而非接线。</strong> 这篇的新数据表明：追逐时扫掠偏向目标、静止时扫掠先于定向、倒退时扫掠反转。三者都可由<strong>同一个可调参数</strong>解释——扫掠的「指向」由一个可在线更新的信号（运动方向 + 注意/目标位置）加权，而不需要改变任何解剖连接。倒退反转让这一点无可辩驳：若扫掠方向由头部朝向硬接线，倒退时（头朝前、身往后）扫掠仍应朝前；实际它跟着运动/注意走。这是「增益调制（gain modulation）」的经典判据——神经系统最常用的计算手段：<strong>不改变线路，只改变权重</strong>。</p><p><strong>第四段：REM 中的复现说明它不依赖感觉输入。</strong> 睡眠中无外部刺激、无明显运动，扫掠调制仍出现，说明这套增益信号来自内部（运动指令的副本/内部模型），而不是感觉反馈。这给出可证伪预测：若切断本体感觉反馈而保留运动意图，调制应基本保留；反之若抑制副下托方向信号，交替与目标导向都应消失，而均匀覆盖则退化为固定偏置。</p><hr><h2 id="⚛️-第一性原理层" tabindex="-1">⚛️ 第一性原理层 <a class="header-anchor" href="#⚛️-第一性原理层" aria-label="Permalink to &quot;⚛️ 第一性原理层&quot;">​</a></h2><h3 id="原理一-可预报性由「被解析的有效自由度」决定-不是由网格间距决定" tabindex="-1">原理一：可预报性由「被解析的有效自由度」决定，不是由网格间距决定 <a class="header-anchor" href="#原理一-可预报性由「被解析的有效自由度」决定-不是由网格间距决定" aria-label="Permalink to &quot;原理一：可预报性由「被解析的有效自由度」决定，不是由网格间距决定&quot;">​</a></h3><p>WN-C 用粗网格赢过公里级区域模式，表面上是反直觉，实质上是一条老定律的复述：<strong>预报技巧取决于初始条件中保留下来的、与未来观测量有因果耦合的自由度数量，而不取决于你把网格切得多细。</strong> 网格加密如果只是把一个在参数化里被平均掉的次网格过程「显式化」，它增加的是细节而非可预报信息——因为在混沌系统里，被新增的自由度自身就是不可预报的（误差以 Lyapunov 率指数增长），它们对目标量（强度）的贡献在时间平均下被抵消。</p><p>这条原理有一个可操作的形式：把目标量对初始场的**敏感性（sensitivity）**在空间尺度上做谱分解，如果敏感性集中在 &gt; 500 km 的波段，那么任何 &lt; 10 km 的解析都是浪费；反之若敏感性有眼墙尺度的峰，粗模型必然系统性失准。这给出了可证伪预测：对快速增强个例，强度对初始场的敏感性谱应在天气尺度（synoptic）波段有主峰；而对路径（track），主峰应出现在更大的波段——这解释了为什么路径预报早被粗模型攻下，强度预报要晚得多。它也预测了失败模式：当强度变化由眼墙替换（eyewall replacement cycle）这类纯内核过程主导时，粗模型的技巧应当掉下来——这是检验该解释的判决性实验。</p><h3 id="原理二-任何「看数据决定是否停」的程序-都必须为持续有效性付费" tabindex="-1">原理二：任何「看数据决定是否停」的程序，都必须为持续有效性付费 <a class="header-anchor" href="#原理二-任何「看数据决定是否停」的程序-都必须为持续有效性付费" aria-label="Permalink to &quot;原理二：任何「看数据决定是否停」的程序，都必须为持续有效性付费&quot;">​</a></h3><p>AV-AIVAT 的 74 倍、PAC 界的 (d+log(1/δ))/n 项、以及 StepJack 里「链条越长越容易失手」，是同一个数学结构的三副面孔：<strong>信息量决定精度，而「灵活性」的每一分都从同一个预算里扣。</strong></p><p>置信序列必须在<strong>所有</strong> t 上同时成立（sup over t），因此其宽度不可避免地在 log log t 量级上增长（重对数律给出的自然尺度）——这是「随时可停」的定价：用固定样本区间能拿到的窄区间，在任意停止下买不到。同样的逻辑，agnostic PAC 的 (d+log(1/δ))/n 项是「你事先不知道哪个假设好」的定价：模型选择的自由度必须用 log 项付账。而 StepJack 的增益随链条长度先升后降，是因为每一步都消耗「语境保真度」这一预算，超过某个深度后，智能体的执行损耗盖过了检测规避的收益。</p><p>由此得到一个可检验的推论：任何声称「既能随时停止、又能达到固定预算同等精度」的评测方法，必然在某个未被检验的维度上偷偷花了预算（通常是假设了数据分布或依赖了大样本渐近）。这不是哲学立场，是可被反例推翻的定量断言。</p><hr><h2 id="🔗-交叉关联" tabindex="-1">🔗 交叉关联 <a class="header-anchor" href="#🔗-交叉关联" aria-label="Permalink to &quot;🔗 交叉关联&quot;">​</a></h2><p>本期 10 条看似分散在气象、精密测量、合成生物学、神经科学、药物设计、机器学习理论与安全之间，但它们问的是<strong>同一个问题：一个系统能读出什么，取决于它读的通道有多宽、多细、以及何时停。</strong></p><ul><li><strong>通道宽度</strong>：WN-C 的粗网格不是缺陷而是选择（强度信号本就在大尺度上）；悬浮磁强计把「夹持」这条噪声通道关掉，Q 才成为可用的资源；θ 扫掠是在有限的神经元上用时间换空间；AV-AIVAT 则用置信序列把「继续采样」换成「已足够」。四者都在重新分配「有限带宽」。</li><li><strong>信息的位置</strong>：GLU 权重提取证明参数并非锁在黑盒里——只要你能构造正确的成对查询，内部结构会从输出里渗出来；噬菌体基因组设计证明「功能等价」可以被模型学到，即便序列已远离野生型。两者共同否定一个朴素假设：<strong>表面不同 = 内部不同</strong>。反过来，AI 写 C++ 的质量剖面证明：表面能跑 ≠ 内部健康（耦合与拷贝的开销在源码里，不在通过率里）。</li><li><strong>停止与代价</strong>：PAC 界的维数税、CS 的宽度增长、StepJack 的深度衰减、以及「5–8% 算力」这笔账，都是同一件事——<strong>能力边界不在模型内部，而在「你愿意为多少确定性付多少样本/算力」的兑换率上</strong>。</li></ul><p>与库内主题的深层同构有三处。其一，<code>topics/wind-energy/index.md</code> 的机组载荷与湍流建模，本质与 WN-C 同题：决定疲劳损伤的是<strong>大尺度来流统计</strong>（湍流强度、相干结构），而不是每秒每点的瞬时脉动；把仿真网格加密到 DNS 级并不能改进 20 年寿命估计，改进来自谱模型与尾流叠加的正确性。其二，<code>topics/ai-brain/index.md</code> 的核心主张——「关联的质量决定检索的价值」——与 θ 扫掠是同一命题的两种表述：读取策略即知识。其三，<code>topics/ai-system-architecture/index.md</code> 反复出现的判断「约束定义搜索空间」，在 DCL05 的三元复合物设计与噬菌体基因组重写上同时成立：不是先自由生成再过滤，而是把约束前置为生成条件。</p><p>关键词：WeatherNext Cyclones, WN-C, 热带气旋强度预报, 集合预报, DeepMind, 抗磁悬浮, 磁强计, 32 fT/√Hz, 光力学, Dmitry Budker, 噬菌体基因组, ΦX174, 基因组语言模型, Brian Hie, 冷冻电镜, CLIP1-LTK, PROTAC, DCL05, DC50, 靶向蛋白降解, theta sweeps, 相位进动, parasubiculum, Moser, Neuropixels, GLU 权重提取, 有限差分曲率, agnostic PAC, 样本复杂度, 7×10⁸, 置信序列, AIVAT, 顺序检验, anytime-valid, StepJack, 间接提示注入, CUA, 静态分析, 10.1038/s41586-026-10953-2, 10.1126/science.aec2657, 10.1126/science.adx1707, 10.1126/science.aef4184, 10.1073/pnas.2535979123, arXiv:2608.06631, arXiv:2608.06363, arXiv:2608.06477, arXiv:2608.06362, arXiv:2608.06640 关联：topics/wind-energy/index.md, topics/physics/index.md, topics/neuroscience/index.md, topics/biomedicine/index.md, topics/cybersecurity/index.md, topics/vibe-coding/index.md, topics/ai-brain/index.md, topics/ai-system-architecture/index.md, topics/intelligence-self-learning/index.md, topics/quantum-physics/index.md, topics/investment-methods/index.md, topics/quality-products/index.md, topics/science-news/index.md</p>',121)])])}const m=t(s,[["render",a]]);export{h as __pageData,m as default};
